<?php require 'config.php';require_user();$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['user_id']]);$orders=$s->fetchAll();$detailId=(int)($_GET['id']??0);$detail=null;$items=[];if($detailId){$s=$pdo->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$s->execute([$detailId,$_SESSION['user_id']]);$detail=$s->fetch();if($detail){$s=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$detailId]);$items=$s->fetchAll();}}$title='My Orders | MediHome';require 'includes/header.php';?><div class="pagehead"><span class="eyebrow">Your purchases</span><h1>My orders</h1><p>Review your order history and status updates.</p></div><?php if($detail):?><div class="detail"><h2>Order #<?=(int)$detail['id']?> · <?=e($detail['status'])?></h2><p><?=e($detail['created_at'])?> · <?=e($detail['address'])?></p><div class="tablewrap"><table class="table"><tr><th>Item</th><th>Qty</th><th>Price</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['medicine_name'])?></td><td><?=(int)$i['quantity']?></td><td><?=money($i['unit_price'])?></td></tr><?php endforeach;?></table></div><h2><?=money($detail['total'])?></h2></div><?php endif;?><?php if(!$orders):?><div class="empty"><h2>No orders yet</h2><a class="btn" href="/MediHome/medicines.php">Shop medicines</a></div><?php else:?><div class="tablewrap"><table class="table"><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr><?php foreach($orders as $o):?><tr><td>#<?=(int)$o['id']?></td><td><?=e($o['created_at'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td><td><a class="btn ghost" href="/MediHome/orders.php?id=<?=(int)$o['id']?>">View</a></td></tr><?php endforeach;?></table></div><?php endif;?><?php require 'includes/footer.php';?>